import { useEffect, useState } from "react";
import API from "../services/adminApi";
import "../styles/Providers.css";

const Providers = () => {
  const [providers, setProviders] = useState([]);
  const [search, setSearch] = useState("");
  const [selectedProvider, setSelectedProvider] = useState(null);

  const fetchProviders = async () => {
    try {
      const res = await API.get("/providers");
      setProviders(res.data);
    } catch (err) {
      console.log("Error fetching providers");
    }
  };

  useEffect(() => {
    fetchProviders();
  }, []);

  const handleApprove = async (id) => {
  const confirmAction = window.confirm(
    "Are you sure you want to approve this provider?"
  );

  if (!confirmAction) return;

  await API.put(`/approve-provider/${id}`);
  fetchProviders();
};

const handleBlock = async (id) => {
  const confirmAction = window.confirm(
    "Are you sure you want to change block status?"
  );

  if (!confirmAction) return;

  await API.put(`/block-provider/${id}`);
  fetchProviders();
};

  const filteredProviders = providers.filter((provider) =>
    provider.name.toLowerCase().includes(search.toLowerCase())
  );

  return (
  <div className="providers-container">
    <div className="providers-header">
      <h2>Providers Management</h2>

      <input
        type="text"
        placeholder="Search provider..."
        value={search}
        onChange={(e) => setSearch(e.target.value)}
        className="search-input"
      />
    </div>

    <div className="table-wrapper">
      <table>
        <thead>
  <tr>
    <th>Name</th>
    <th>Email</th>
    <th>Phone</th>
    <th>Joined</th>
    <th>Approval</th>
    <th>Status</th>
    <th>Actions</th>
  </tr>
</thead>

        <tbody>
          {filteredProviders.map((provider) => (
            <tr key={provider.user_id}>
              <td>{provider.user_id}</td>
              <td>{provider.name}</td>
              <td>{provider.email}</td>

              <td>
                {provider.is_approved ? (
                  <span className="badge badge-approved">
                    Approved
                  </span>
                ) : (
                  <span className="badge badge-pending">
                    Pending
                  </span>
                )}
              </td>

              <td>
                {provider.is_blocked ? (
                  <span className="badge badge-blocked">
                    Blocked
                  </span>
                ) : (
                  <span className="badge badge-active">
                    Active
                  </span>
                )}
              </td>

              <td className="action-buttons">
                {!provider.is_approved && (
                  <button
                    className="btn btn-approve"
                    onClick={() =>
                      handleApprove(provider.user_id)
                    }
                  >
                    Approve
                  </button>
                )}

                <button
                  className="btn btn-block"
                  onClick={() =>
                    handleBlock(provider.user_id)
                  }
                >
                  {provider.is_blocked
                    ? "Unblock"
                    : "Block"}
                </button>

                <button
                  className="btn btn-view"
                  onClick={() =>
                    setSelectedProvider(provider)
                  }
                >
                  View
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>

    {/* Modal */}
    {selectedProvider && (
      <div className="modal-overlay">
        <div className="modal">
          <h3>Provider Details</h3>

          <p><strong>ID:</strong> {selectedProvider.user_id}</p>
          <p><strong>Name:</strong> {selectedProvider.name}</p>
          <p><strong>Email:</strong> {selectedProvider.email}</p>

          <button
            className="btn btn-close"
            onClick={() => setSelectedProvider(null)}
          >
            Close
          </button>
        </div>
      </div>
    )}
  </div>
);
};

export default Providers;
